from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = dict(jumps)
    resolved = [None if cell in jump else cell for cell in range(n + 1)]

    for cell in range(n + 1):
        path = []
        current = cell
        while resolved[current] is None:
            path.append(current)
            current = jump[current]
        destination = resolved[current]
        for current in path:
            resolved[current] = destination

    transitions = {}
    reverse = [[] for _ in range(n + 1)]
    reachable = [0]
    seen = {0}

    for cell in reachable:
        if cell == n:
            continue

        counts = {}
        for roll in range(1, m + 1):
            landing = cell + roll
            if landing > n:
                landing = 2 * n - landing
            destination = resolved[landing]
            counts[destination] = counts.get(destination, 0) + 1

        transitions[cell] = counts
        for destination in counts:
            reverse[destination].append(cell)
            if destination not in seen:
                seen.add(destination)
                reachable.append(destination)

    # Every reachable state must have a path to the terminal state.
    can_finish = {n}
    stack = [n]
    while stack:
        destination = stack.pop()
        for cell in reverse[destination]:
            if cell not in can_finish:
                can_finish.add(cell)
                stack.append(cell)

    if any(cell not in can_finish for cell in reachable):
        return None

    states = [cell for cell in reachable if cell != n]
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)

    # m * E[cell] - sum(count * E[destination]) = m.
    matrix = [[0] * (size + 1) for _ in range(size)]
    for cell, i in index.items():
        matrix[i][i] = m
        matrix[i][size] = m
        for destination, count in transitions[cell].items():
            if destination != n:
                matrix[i][index[destination]] -= count

    # Bareiss elimination keeps all intermediate entries integral.
    # For this absorbing-chain matrix, all leading pivots are nonzero.
    previous_pivot = 1
    for k in range(size - 1):
        pivot_row = matrix[k]
        pivot = pivot_row[k]
        for i in range(k + 1, size):
            row = matrix[i]
            factor = row[k]
            for j in range(k + 1, size + 1):
                row[j] = (
                    pivot * row[j] - factor * pivot_row[j]
                ) // previous_pivot
            row[k] = 0
        previous_pivot = pivot

    expectation = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * expectation[j]
        expectation[i] = value / matrix[i][i]

    answer = expectation[index[0]]
    return [answer.numerator, answer.denominator]
